/**
 * Autonomous engine — statistical honesty battery (WP6, pure).
 *
 * Deriv digits are generated by a CSPRNG: i.i.d. uniform. Recovery contracts
 * therefore carry NEGATIVE expectation and no selection rule can find edge.
 * The honesty battery exists to prove that, per market, on an ongoing basis —
 * and to gate the ONLY permitted data-driven adjustment (a bounded REDUCTION
 * of the RCI margin weight, never a stake increase) behind evidence strong
 * enough to survive multiple testing:
 *
 *   1. A per-market battery of ≥5000 ticks: digit-uniformity χ², serial
 *      correlation lags 1–5, a 10×10 transition-matrix χ² (independence), and
 *      a Wald–Wolfowitz runs test; Rise/Fall tapes add a sign-runs test.
 *   2. Benjamini–Hochberg at q = 0.10 across the battery (and across markets)
 *      controls the false-discovery rate of the whole screen.
 *   3. An anytime-valid e-process (Beta-mixture martingale) on each contract's
 *      hit rate vs its fair p0 — valid under optional stopping, so it can be
 *      watched forever without inflating the Type-I error.
 *   4. Tilt activates ONLY when e ≥ 20 AND the battery is BH-significant,
 *      auto-disables below e < 1/20, and multiplies the RCI margin weight by a
 *      factor in [TILT_FLOOR, 1] — reducing margin-aversion at most by half,
 *      never raising stakes, never creating a positive-expectation claim.
 *
 * Everything here is dependency-free: the χ² tail uses an in-repo regularised
 * incomplete gamma, the normal tail an Abramowitz–Stegun erf approximation.
 */

export interface TestResult {
  name: string;
  statistic: number;
  pValue: number;
  /** True when the null (i.i.d. fair tape) is NOT rejected at alpha. */
  pass: boolean;
}

export interface BatteryReport {
  n: number;
  tests: TestResult[];
  /** Smallest p-value in the battery (the one BH screens). */
  minP: number;
}

export const TILT_EVIDENCE_ON = 20;
export const TILT_EVIDENCE_OFF = 1 / 20;
export const TILT_FLOOR = 0.5;
export const BH_Q = 0.10;
export const MIN_BATTERY_TICKS = 5000;

// ── Special functions (in-repo, no deps) ──────────────────────────────────────

function logGamma(x: number): number {
  // Lanczos approximation (g = 7).
  const c = [
    0.99999999999980993, 676.5203681218851, -1259.1392167224028,
    771.32342877765313, -176.61502916214059, 12.507343278686905,
    -0.13857109526572012, 9.9843695780195716e-6, 1.5056327351493116e-7,
  ];
  if (x < 0.5) return Math.log(Math.PI / Math.sin(Math.PI * x)) - logGamma(1 - x);
  const z = x - 1;
  let a = c[0];
  for (let i = 1; i < 9; i++) a += c[i] / (z + i);
  const t = z + 7.5;
  return 0.5 * Math.log(2 * Math.PI) + (z + 0.5) * Math.log(t) - t + Math.log(a);
}

/** Lower regularised incomplete gamma P(a, x) — series / continued fraction. */
function gammaP(a: number, x: number): number {
  if (x <= 0) return 0;
  if (x < a + 1) {
    // Series.
    let sum = 1 / a;
    let term = sum;
    for (let n = 1; n < 400; n++) {
      term *= x / (a + n);
      sum += term;
      if (Math.abs(term) < Math.abs(sum) * 1e-14) break;
    }
    return sum * Math.exp(-x + a * Math.log(x) - logGamma(a));
  }
  // Continued fraction for Q(a,x), Lentz's method (NR gcf).
  let c = 1e300;
  let d = 1 / (x + 1 - a);
  let h = d;
  for (let i = 1; i < 400; i++) {
    const an = i * (a - i);
    const bn = x + 2 * i + 1 - a;
    d = bn + an * d;
    if (Math.abs(d) < 1e-300) d = 1e-300;
    c = bn + an / c;
    if (Math.abs(c) < 1e-300) c = 1e-300;
    d = 1 / d;
    const delta = c * d;
    h *= delta;
    if (Math.abs(delta - 1) < 1e-14) break;
  }
  const q = Math.exp(-x + a * Math.log(x) - logGamma(a)) * h;
  return 1 - q;
}

/** Two-sided survival of the χ² distribution: P(X ≥ stat | df). */
export function chiSquarePValue(stat: number, df: number): number {
  if (stat <= 0) return 1;
  return Math.max(0, Math.min(1, 1 - gammaP(df / 2, stat / 2)));
}

function erf(x: number): number {
  // Abramowitz–Stegun 7.1.26 (|ε| < 1.5e-7).
  const sign = x < 0 ? -1 : 1;
  const ax = Math.abs(x);
  const t = 1 / (1 + 0.3275911 * ax);
  const poly = t * (0.254829592 + t * (-0.284496736 + t * (1.421413741 + t * (-1.453152027 + t * 1.061405429))));
  return sign * (1 - poly * Math.exp(-ax * ax));
}

export function normalTwoSidedP(z: number): number {
  const p = 1 - 0.5 * (1 + erf(Math.abs(z) / Math.SQRT2));
  return Math.max(0, Math.min(1, 2 * p));
}

// ── Battery tests on digit tapes ──────────────────────────────────────────────

/** χ² goodness-of-fit of the digit counts against uniform(0..9). */
export function chiSquareUniformity(digits: number[], alpha = 0.05): TestResult {
  const counts = new Array(10).fill(0);
  for (const d of digits) counts[Math.abs(Math.floor(d)) % 10] += 1;
  const expected = digits.length / 10;
  let stat = 0;
  for (let i = 0; i < 10; i++) stat += (counts[i] - expected) ** 2 / expected;
  const pValue = chiSquarePValue(stat, 9);
  return { name: "digit-uniformity", statistic: stat, pValue, pass: pValue >= alpha };
}

/** Serial correlation of the digit sequence at lags 1..maxLag. */
export function serialCorrelation(digits: number[], maxLag = 5, alpha = 0.05): TestResult[] {
  const n = digits.length;
  const mean = digits.reduce((s, d) => s + d, 0) / n;
  const denom = digits.reduce((s, d) => s + (d - mean) ** 2, 0);
  const out: TestResult[] = [];
  for (let lag = 1; lag <= maxLag; lag++) {
    let num = 0;
    for (let i = lag; i < n; i++) num += (digits[i] - mean) * (digits[i - lag] - mean);
    const r = denom > 0 ? num / denom : 0;
    const z = r * Math.sqrt(n - lag);
    const pValue = normalTwoSidedP(z);
    out.push({ name: `serial-lag${lag}`, statistic: r, pValue, pass: pValue >= alpha });
  }
  return out;
}

/** 10×10 transition-matrix χ² test of independence (df = 81). */
export function transitionChiSquare(digits: number[], alpha = 0.05): TestResult {
  const n = digits.length;
  const T: number[][] = Array.from({ length: 10 }, () => new Array(10).fill(0));
  for (let i = 1; i < n; i++) T[digits[i - 1] % 10][digits[i] % 10] += 1;
  const rowSum = T.map((row) => row.reduce((s, v) => s + v, 0));
  const colSum = new Array(10).fill(0);
  for (let i = 0; i < 10; i++) for (let j = 0; j < 10; j++) colSum[j] += T[i][j];
  const total = n - 1;
  let stat = 0;
  for (let i = 0; i < 10; i++) {
    if (rowSum[i] === 0) continue;
    for (let j = 0; j < 10; j++) {
      const expected = (rowSum[i] * colSum[j]) / total;
      if (expected > 0) stat += (T[i][j] - expected) ** 2 / expected;
    }
  }
  const pValue = chiSquarePValue(stat, 81);
  return { name: "transition-independence", statistic: stat, pValue, pass: pValue >= alpha };
}

/** Wald–Wolfowitz runs test on a boolean sequence (null: i.i.d. fair mixing). */
export function runsTest(bits: boolean[], alpha = 0.05): TestResult {
  const n = bits.length;
  const n1 = bits.filter(Boolean).length;
  const n0 = n - n1;
  if (n < 10 || n1 === 0 || n0 === 0) {
    return { name: "runs", statistic: 0, pValue: 1, pass: true };
  }
  let runs = 1;
  for (let i = 1; i < n; i++) if (bits[i] !== bits[i - 1]) runs += 1;
  const expected = (2 * n1 * n0) / n + 1;
  const variance = (2 * n1 * n0 * (2 * n1 * n0 - n)) / (n * n * (n - 1));
  const z = variance > 0 ? (runs - expected) / Math.sqrt(variance) : 0;
  const pValue = normalTwoSidedP(z);
  return { name: "runs", statistic: z, pValue, pass: pValue >= alpha };
}

/** Runs test on Rise/Fall price signs. */
export function riseFallRunsTest(prices: number[], alpha = 0.05): TestResult {
  const bits: boolean[] = [];
  for (let i = 1; i < prices.length; i++) bits.push(prices[i] >= prices[i - 1]);
  const r = runsTest(bits, alpha);
  return { ...r, name: "rise-fall-sign-runs" };
}

/** Full digit battery for one market (spec: ≥ 5000 ticks). */
export function digitBattery(digits: number[], alpha = 0.05): BatteryReport {
  const tests: TestResult[] = [
    chiSquareUniformity(digits, alpha),
    ...serialCorrelation(digits, 5, alpha),
    transitionChiSquare(digits, alpha),
    runsTest(digits.map((d) => d >= 5), alpha),
  ];
  return { n: digits.length, tests, minP: Math.min(...tests.map((t) => t.pValue)) };
}

// ── Benjamini–Hochberg ────────────────────────────────────────────────────────

/**
 * BH step-up at level q. Returns adjusted q-values and per-test significance.
 */
export function benjaminiHochberg(pValues: number[], q = BH_Q): { qValues: number[]; significant: boolean[] } {
  const m = pValues.length;
  if (m === 0) return { qValues: [], significant: [] };
  const order = pValues.map((p, i) => ({ p, i })).sort((a, b) => a.p - b.p);
  const qValues = new Array(m).fill(0);
  let prev = 1;
  for (let rank = m; rank >= 1; rank--) {
    const { p, i } = order[rank - 1];
    const adj = Math.min(prev, (p * m) / rank);
    qValues[i] = adj;
    prev = adj;
  }
  return { qValues, significant: qValues.map((qv) => qv <= q) };
}

// ── Anytime-valid e-process on the hit rate ───────────────────────────────────

export interface EProcessState {
  /** Number of settled recovery trades observed for this contract. */
  n: number;
  wins: number;
  /** Current e-value (non-negative martingale, starts at 1). */
  e: number;
  /** Cumulative log-likelihood ratio per alternative grid point. */
  logLike: number[];
  /** The alternative p1 grid (fixed at construction). */
  grid: number[];
  p0: number;
}

const GRID_POINTS = 15;

/**
 * Create an e-process for H0: p ≤ p0 vs H1: p > p0 using a uniform mixture of
 * point alternatives above p0. The mixture likelihood ratio is a non-negative
 * martingale under H0, hence valid at every stopping time (Ville).
 */
export function createEProcess(p0: number): EProcessState {
  const lo = Math.min(0.98, p0 + 0.02);
  const hi = Math.min(0.99, p0 + 0.35);
  const grid: number[] = [];
  for (let i = 0; i < GRID_POINTS; i++) grid.push(lo + ((hi - lo) * i) / (GRID_POINTS - 1));
  return { n: 0, wins: 0, e: 1, logLike: new Array(GRID_POINTS).fill(0), grid, p0 };
}

/**
 * One settled outcome. e = (1/K)·Σ_i exp(logLike_i) with the uniform mixture
 * kept FIXED (no renormalisation) — that is what makes it a test martingale.
 * Returns the updated state (mutated in place).
 */
export function stepEProcess(state: EProcessState, won: boolean): EProcessState {
  const { p0, grid, logLike } = state;
  let maxLog = -Infinity;
  for (let i = 0; i < grid.length; i++) {
    const p1 = grid[i];
    logLike[i] += won
      ? Math.log(p1) - Math.log(p0)
      : Math.log(1 - p1) - Math.log(1 - p0);
    maxLog = Math.max(maxLog, logLike[i]);
  }
  let sum = 0;
  for (let i = 0; i < grid.length; i++) sum += Math.exp(logLike[i] - maxLog);
  const logE = maxLog + Math.log(sum) - Math.log(grid.length);
  state.e = Math.min(1e12, Math.exp(Math.min(27, logE)));
  state.n += 1;
  if (won) state.wins += 1;
  return state;
}

// ── Tilt gate ─────────────────────────────────────────────────────────────────

export interface TiltDecision {
  active: boolean;
  /** Multiplier for the RCI margin weight w1 — always in [TILT_FLOOR, 1]. */
  marginWeightFactor: number;
  eValue: number;
  batterySignificant: boolean;
  reason: string;
}

/**
 * Hysteresis gate: tilt turns ON only with e ≥ 20 AND a BH-significant
 * battery; it turns OFF below e < 1/20 (or whenever the kill switch is off or
 * the battery is clean again). While active it multiplies the margin weight by
 * TILT_FLOOR at most — a bounded reduction, never a stake increase.
 */
export function tiltGate(input: {
  eValue: number;
  batterySignificant: boolean;
  currentlyActive: boolean;
  enabled: boolean;
}): TiltDecision {
  if (!input.enabled) {
    return { active: false, marginWeightFactor: 1, eValue: input.eValue, batterySignificant: input.batterySignificant, reason: "kill-switch off" };
  }
  if (input.currentlyActive) {
    if (input.eValue < TILT_EVIDENCE_OFF || !input.batterySignificant) {
      return { active: false, marginWeightFactor: 1, eValue: input.eValue, batterySignificant: input.batterySignificant, reason: input.eValue < TILT_EVIDENCE_OFF ? "e-value collapsed below 1/20" : "battery no longer significant" };
    }
    return { active: true, marginWeightFactor: TILT_FLOOR, eValue: input.eValue, batterySignificant: true, reason: "sustained evidence (hysteresis hold)" };
  }
  if (input.eValue >= TILT_EVIDENCE_ON && input.batterySignificant) {
    return { active: true, marginWeightFactor: TILT_FLOOR, eValue: input.eValue, batterySignificant: true, reason: "e ≥ 20 and battery BH-significant" };
  }
  return { active: false, marginWeightFactor: 1, eValue: input.eValue, batterySignificant: input.batterySignificant, reason: "evidence below gate" };
}
